package com.voicebookai.app;
import android.Manifest; import android.app.Activity; import android.content.*; import android.content.pm.PackageManager; import android.media.*; import android.os.*; import android.speech.*; import android.view.*; import android.widget.*; import java.io.*; import java.text.*; import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root, notes; EditText topic, note; TextView status, audioStatus; SharedPreferences prefs; SpeechRecognizer sr; boolean listening=false; MediaRecorder recorder; MediaPlayer player; File audio;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);} TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff202124);t.setPadding(4,dp(6),4,dp(6));return t;} Button btn(String s){Button b=new Button(this);b.setText(s);return b;}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("voicebook",0); ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(12),dp(16),dp(20));root.setBackgroundColor(0xfffff5df);sc.addView(root);setContentView(sc);
 TextView title=label("📒 VoiceBook AI",28);title.setGravity(Gravity.CENTER);title.setTextColor(0xff6039a5);root.addView(title);root.addView(label("Speak your notes. Organise them by topic.",15));status=label("Ready",14);root.addView(status);
 root.addView(label("TOPIC",14));topic=new EditText(this);topic.setSingleLine(true);topic.setText("General");topic.setHint("Topic name");root.addView(topic);Button nt=btn("＋ New topic");root.addView(nt);nt.setOnClickListener(v->{String s=topic.getText().toString().trim();if(s.isEmpty())s="Topic "+new SimpleDateFormat("HHmm",Locale.getDefault()).format(new Date());topic.setText(s);status.setText("Current topic: "+s);});
 root.addView(label("NOTE",14));note=new EditText(this);note.setMinLines(4);note.setGravity(Gravity.TOP);note.setHint("Type a note or use speech recognition");root.addView(note);
 Button listen=btn("🎙 Start listening");root.addView(listen);listen.setOnClickListener(v->{if(listening){if(sr!=null){sr.cancel();}listening=false;listen.setText("🎙 Start listening");status.setText("Listening stopped.");}else startSpeech(listen);});
 Button save=btn("💾 Save note");root.addView(save);save.setOnClickListener(v->saveNote());
 root.addView(label("AUDIO RECORDING",17));audioStatus=label("No recording yet.",13);root.addView(audioStatus);Button rec=btn("⏺ Start audio recording");root.addView(rec);rec.setOnClickListener(v->{if(recorder==null)startRecording(rec);else stopRecording(rec);});Button play=btn("▶ Play last recording");root.addView(play);play.setOnClickListener(v->playAudio());root.addView(label("SAVED NOTES",20));notes=new LinearLayout(this);notes.setOrientation(1);root.addView(notes);refresh();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},9);
 }
 void startSpeech(Button button){if(!SpeechRecognizer.isRecognitionAvailable(this)){status.setText("Speech recognition is unavailable on this phone.");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},9);return;}if(sr!=null)sr.destroy();sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){status.setText("Listening… speak now.");}public void onBeginningOfSpeech(){}public void onRmsChanged(float x){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){status.setText("Processing speech…");}public void onError(int e){listening=false;button.setText("🎙 Start listening");status.setText("Stopped. Tap Start listening to try again.");}public void onResults(Bundle b){listening=false;button.setText("🎙 Start listening");ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a==null||a.isEmpty())return;String s=a.get(0).trim(),lo=s.toLowerCase(Locale.ROOT);if(lo.equals("new topic")||lo.startsWith("new topic ")){String n=s.length()>9?s.substring(10).trim():"";if(n.isEmpty())n="Topic "+new SimpleDateFormat("HHmm",Locale.getDefault()).format(new Date());topic.setText(n);status.setText("Created topic: "+n);}else{String old=note.getText().toString();note.setText(old.isEmpty()?s:old+"\n"+s);note.setSelection(note.length());status.setText("Speech added to note.");}}public void onPartialResults(Bundle b){}public void onEvent(int i,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.getDefault());listening=true;button.setText("■ Stop listening");sr.startListening(i);}
 void saveNote(){String body=note.getText().toString().trim(),top=topic.getText().toString().trim();if(body.isEmpty()){status.setText("Write or speak a note first.");return;}if(top.isEmpty())top="General";String id=String.valueOf(System.currentTimeMillis());String value=top+"\n"+new SimpleDateFormat("dd MMM yyyy, HH:mm",Locale.getDefault()).format(new Date())+"\n"+body;prefs.edit().putString("note_"+id,value).apply();note.setText("");status.setText("Note saved under "+top);refresh();}
 void refresh(){if(notes==null)return;notes.removeAllViews();ArrayList<String> keys=new ArrayList<>();for(String k:prefs.getAll().keySet())if(k.startsWith("note_"))keys.add(k);Collections.sort(keys,Collections.reverseOrder());if(keys.isEmpty()){notes.addView(label("Your saved notes will appear here.",14));return;}for(String k:keys){String[]p=prefs.getString(k,"").split("\n",3);TextView t=label("📌 "+p[0]+(p.length>1?"\n"+p[1]:"")+(p.length>2?"\n"+p[2]:""),14);t.setBackgroundColor(0xffffffff);t.setPadding(dp(10),dp(10),dp(10),dp(10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(4));notes.addView(t,lp);}}
 File audioFile(){return new File(getFilesDir(),"voicebook-last.3gp");} void startRecording(Button b){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},9);return;}try{audio=audioFile();if(Build.VERSION.SDK_INT>=31)recorder=new MediaRecorder(this);else recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.THREE_GPP);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AMR_NB);recorder.setOutputFile(audio.getAbsolutePath());recorder.prepare();recorder.start();b.setText("■ Stop audio recording");audioStatus.setText("Recording… tap stop when finished.");}catch(Exception e){audioStatus.setText("Could not record. Check microphone permission.");if(recorder!=null){recorder.release();recorder=null;}}}
 void stopRecording(Button b){try{recorder.stop();prefs.edit().putString("last_audio",audio.getAbsolutePath()).apply();audioStatus.setText("Recording saved on this phone.");}catch(Exception e){audioStatus.setText("Recording too short; try again.");}finally{recorder.release();recorder=null;b.setText("⏺ Start audio recording");}}
 void playAudio(){String p=prefs.getString("last_audio","");if(p.isEmpty()||!new File(p).exists()){audioStatus.setText("Record audio first.");return;}try{if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(p);player.setOnCompletionListener(m->{m.release();player=null;audioStatus.setText("Playback finished.");});player.prepare();player.start();audioStatus.setText("Playing last recording…");}catch(Exception e){audioStatus.setText("Could not play recording.");}}
 protected void onDestroy(){super.onDestroy();if(sr!=null)sr.destroy();if(player!=null)player.release();if(recorder!=null)try{recorder.release();}catch(Exception e){}}
}
